        QCOMPARE(format.bottomBorder(), 1.0); QCOMPARE(format.bottomBorderStyle(), QTextFrameFormat::BorderStyle_Dotted);
        QCOMPARE(format.leftBorder(), 2.0); QCOMPARE(format.rightBorder(), 0.0);
