        doc.documentLayout()->documentSize(); QCOMPARE(doc.documentLayout()->property("_wikidictParagraphBoxLayoutError").toInt(), 0);
        QVERIFY(doc.documentLayout()->frameBoundingRect(actual).isValid()); QCOMPARE(doc.toRawText(), raw);
