        QTRY_COMPARE(document->textWidth(), qreal(witnessBrowser->viewport()->width()));
        window.resize(900, 700); QTRY_COMPARE(window.contentsRect().width(), 900);
        QTRY_COMPARE(document->textWidth(), qreal(witnessBrowser->viewport()->width()));
