        QTRY_VERIFY(qAbs(splitter->sizes().value(0) - wideSizes.value(0)) <= 2);
        qInfo().noquote() << "WIDE_RESTORE_SETTLED_GEOMETRY" << QJsonDocument(restoredGeometry()).toJson(QJsonDocument::Compact);
